  select * from jsonb_to_recordset('[{"stable_key":"ocean-steam","name":"海の不思議を、ひとつ読む","summary":"写真やワークシートから、海の生き物と地球環境の関係に触れる。","url":"https://www.jamstec.go.jp/steam/","source_name":"JAMSTEC","checked_on":"2026-09-11","category":"material","kind":"自宅・教材","online":true,"free":true,"prefecture":null,"grades":["j1","j2","j3"],"domains":["ecology","environment","engineering"],"verbs":["dig","observe"],"conditions":[["対象","小中学生向けの教材など。巻ごとに対象が異なります。"],["費用","教材のダウンロードは無料"],["場所","オンライン・家庭学習でも利用可"]],"reason":"海の写真・観測・環境の問いを扱う教材。生き物と環境のつながりを、観察する視点で考えられます。","first_step":"教材の見出しから、気になる問いを1つ選ぶ。","deadline":null},{"stable_key":"scratch-create","name":"Scratchで小さな作品を作る","summary":"ブロックを組み合わせて、キャラクター・音・動きを作る。","url":"https://scratch.mit.edu/ideas","source_name":"Scratch Foundation","checked_on":"2026-09-11","category":"material","kind":"自宅・制作","online":true,"free":true,"prefecture":null,"grades":[],"domains":["information","media","design"],"verbs":["make"],"conditions":[["費用","Scratchの利用は無料"],["機器","制作にはPC・タブレット推奨"],["公開","作品の公開・アカウント設定は外部サイトで確認"]],"reason":"プログラムの順番と、絵・音による表現を同時に試せます。遊びを作る入口にもなります。","first_step":"気になるチュートリアルを1つ開き、動きか音を1つ変えてみる。","deadline":null},{"stable_key":"coderdojo","name":"近くのCoderDojoを探す","summary":"学校の外で、プログラミングや電子工作を主体的に学ぶ活動。","url":"https://coderdojo.jp/","source_name":"CoderDojo Japan","checked_on":"2026-09-11","category":"continuing","kind":"学外・継続活動","online":false,"free":false,"prefecture":null,"grades":[],"domains":["information","media"],"verbs":["make"],"conditions":[["場所","全国の各道場。オンライン開催の有無も個別確認"],["参加","対象年齢・持ち物・申込方法は各道場で確認"],["費用","参加先の案内で確認。交通費・機器も考慮"]],"reason":"ScratchやWeb制作など、興味に合わせて取り組む地域の活動です。扱う内容は道場ごとに違います。","first_step":"近くの道場を1つ選び、開催案内を確認する。","deadline":null},{"stable_key":"guitar-anatomy","name":"ギターの音色は、どこで変わる？","summary":"ピックアップやエフェクター、木材と楽器の仕組みを図から知る。","url":"https://www.yamaha.com/ja/musical_instrument_guide/electric_guitar/","source_name":"ヤマハ 楽器解体全書","checked_on":"2026-09-11","category":"material","kind":"自宅・読みもの","online":true,"free":true,"prefecture":null,"grades":[],"domains":["sound","design"],"verbs":["dig"],"conditions":[["形式","Web記事。読むだけでも利用できます"],["費用","記事の閲覧は無料"],["内容","仕組み・奏法・製作など。学問への接続は本アプリの編集です"]],"reason":"音の仕組みと、楽器の形・材料を同じ対象から見られます。音響とデザインをつなぐ読みものです。","first_step":"「しくみ」から気になる見出しを選ぶ。楽器の購入は不要。","deadline":null},{"stable_key":"fermentation","name":"身近な調味料と「発酵」の不思議","summary":"味噌や醤油など、発酵食品を支える微生物の働きを知る。","url":"https://www.maff.go.jp/j/pr/aff/2211/spe1_01.html","source_name":"農林水産省","checked_on":"2026-09-11","category":"material","kind":"自宅・読みもの","online":true,"free":true,"prefecture":null,"grades":[],"domains":["food","ecology"],"verbs":["dig"],"conditions":[["形式","Web記事・2022年11月号"],["費用","記事の閲覧は無料"],["活動","読む・比べる提案です。発酵実験の手順ではありません"]],"reason":"料理に使う食品を、微生物と成分の変化から見る入口です。好きな料理から科学の問いを見つけられます。","first_step":"家で使う調味料を1つ思い浮かべて、記事に登場するか探す。","deadline":null},{"stable_key":"oshima-school","name":"大島海洋国際高校","summary":"海と関わる学校生活や、潜水部などの活動から高校を知る。","url":"https://www.metro.ed.jp/oosimakaiyokokusai-h/index.html","source_name":"東京都立大島海洋国際高等学校","checked_on":"2026-09-11","category":"school","kind":"高校・進学","online":false,"free":false,"prefecture":"東京都","grades":["j1","j2","j3"],"domains":["ecology"],"verbs":[],"conditions":[["地域","東京都・伊豆大島"],["生活","寄宿舎・通学条件を学校案内で確認"],["入学","応募資格・学費・選抜方法は最新の入試案内へ"]],"reason":"海への興味を、授業だけでなく学校生活や部活動から考える入口。生態学を専門的に学べると保証するものではありません。","deadline":null},{"stable_key":"oshima-diving","name":"大島海洋国際高校の潜水部","summary":"器材の扱いや浮力コントロールなど、活動報告から海との関わりを知る。","url":"https://www.metro.ed.jp/oosimakaiyokokusai-h/activities/2026/08/29_3.html","source_name":"東京都立大島海洋国際高等学校","checked_on":"2026-09-11","category":"club","kind":"校内・部活動","online":false,"free":false,"prefecture":"東京都","grades":["h1","h2","h3"],"domains":["ecology"],"verbs":["observe"],"conditions":[["所属","同校の部活動。在校生の活動報告"],["内容","2026年8月の大会報告"],["参加","活動日・入部条件・費用は学校へ確認"]],"reason":"海への関心を実技の面から広げる活動例です。生物調査そのものを行うという意味ではありません。","deadline":null},{"stable_key":"oshima-visit","name":"学校説明会・部活動体験（大島）","summary":"